 public EquipmentForm(Settings settings){Rigs=Json.Read<List<Rig>>(Json.Write(settings.Rigs));foreach(var rig in Rigs)EquipmentLibrary.NormalizeSmartRig(rig);Style.Form(this);Text="Equipment settings";Style.FitScreen(this,1060,660);var root=Style.Grid(1,38,-100,43);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Equipment setups",20,true),0,0);
 var body=Style.Grid(2,-100);body.ColumnStyles[0].Width=23;body.ColumnStyles[1].Width=77;var left=Style.Grid(1,-100,38);left.Padding=new Padding(0,0,14,0);list=new ListBox{Dock=DockStyle.Fill,BackColor=Style.Card,ForeColor=Style.Text,IntegralHeight=false};left.Controls.Add(list,0,0);var actions=Style.Grid(2,-100);actions.Controls.Add(Style.Button("Add setup",(a,b)=>{if(!Commit())return;Rigs.Add(new Rig{Name="New setup",Camera="",CustomDevice=true,Focal=400,Aperture=60,Mount="Not specified"});editing=-1;RefreshList(Rigs.Count-1);}),0,0);actions.Controls.Add(Style.Button("Remove",(a,b)=>{if(Rigs.Count==1){MessageBox.Show("Keep at least one setup.");return;}int index=list.SelectedIndex;if(index<0)return;Rigs.RemoveAt(index);editing=-1;RefreshList(Math.Min(index,Rigs.Count-1));}),1,0);left.Controls.Add(actions,0,1);body.Controls.Add(left,0,0);
 var fields=Style.Grid(2,56,34,56,56,56,56,34,26,26,-100);name=Input();var setup=Field("Setup name",name);fields.Controls.Add(setup,0,0);fields.SetColumnSpan(setup,2);
 var type=new FlowLayoutPanel{Dock=DockStyle.Fill,Margin=new Padding(0),WrapContents=false};smartOption=new RadioButton{Text="Smart telescope",AutoSize=true,Margin=new Padding(0,5,20,0),AccessibleName="Smart telescope"};customOption=new RadioButton{Text="Custom setup",AutoSize=true,Margin=new Padding(0,5,0,0),AccessibleName="Custom setup"};type.Controls.Add(smartOption);type.Controls.Add(customOption);fields.Controls.Add(type,0,1);otherSpecs=Style.Button("Enter telescope specifications…",(a,b)=>EditOtherSpecs());fields.Controls.Add(otherSpecs,1,1);
 camera=Style.Combo();camera.AccessibleName="Camera";camera.AutoCompleteSource=AutoCompleteSource.ListItems;camera.AutoCompleteMode=AutoCompleteMode.SuggestAppend;Style.DarkCombo(camera);camera.Items.Add("Other");foreach(var item in EquipmentLibrary.All.Where(p=>!p.Smart))camera.Items.Add(item);camera.DropDownWidth=540;cameraField=Field("Camera",camera);telescope=Style.Combo();telescope.AccessibleName="Smart telescope model";Style.DarkCombo(telescope);telescope.Items.AddRange(new object[]{"Seestar S30 Pro","Seestar S30","Seestar S50","Seestar S50 Pro","Other"});telescopeField=Field("Smart telescope",telescope);var deviceSlot=new Panel{Dock=DockStyle.Fill,Margin=new Padding(0)};deviceSlot.Controls.Add(cameraField);deviceSlot.Controls.Add(telescopeField);fields.Controls.Add(deviceSlot,0,2);otherName=Input();otherField=Field("Model name",otherName);fields.Controls.Add(otherField,1,2);
 focal=Number(0,10000,1);aperture=Number(0,1000,1);sw=Number(0,100,3);sh=Number(0,100,3);fields.Controls.Add(Optical("Focal length (mm)",focal),0,3);fields.Controls.Add(Optical("Aperture (mm)",aperture),1,3);fields.Controls.Add(Optical("Sensor width (mm)",sw),0,4);fields.Controls.Add(Optical("Sensor height (mm)",sh),1,4);
 mount=Style.Combo();mount.AccessibleName="Mount";Style.DarkCombo(mount);mount.Items.AddRange(new object[]{"Not specified","Alt-az / smart telescope","Equatorial / tracker","Untracked tripod"});fields.Controls.Add(Field("Mount",mount),0,5);allowed=Input();exposureField=Field("Confirmed app exposures (seconds, comma separated)",allowed);fields.Controls.Add(exposureField,1,5);
 overrideGain=new CheckBox{Text="Use my own gain",Dock=DockStyle.Fill};gain=Number(-100,1000,0);var gainChoice=new Panel{Dock=DockStyle.Fill,Margin=new Padding(0)};smartGain=Style.Label("Gain: app-controlled (not adjustable)",9.5f);gainChoice.Controls.Add(overrideGain);gainChoice.Controls.Add(smartGain);fields.Controls.Add(gainChoice,0,6);fields.Controls.Add(gain,1,6);filter=new CheckBox{Text="Emission-nebula filter available (dual-band / narrowband)",Dock=DockStyle.Fill};mosaic=new CheckBox{Text="Willing to shoot mosaics",Dock=DockStyle.Fill};fields.Controls.Add(filter,0,7);fields.SetColumnSpan(filter,2);fields.Controls.Add(mosaic,0,8);fields.SetColumnSpan(mosaic,2);info=Style.Label("",9);info.TextAlign=ContentAlignment.TopLeft;info.Padding=new Padding(0,8,0,0);fields.Controls.Add(info,0,9);fields.SetColumnSpan(info,2);body.Controls.Add(fields,1,0);root.Controls.Add(body,0,1);
 var footer=Style.Grid(3,-100);footer.ColumnStyles[0].Width=55;footer.ColumnStyles[1].Width=21;footer.ColumnStyles[2].Width=24;preview=Style.Label("",10);footer.Controls.Add(preview,0,0);source=Style.Button("Model source",(a,b)=>{var p=CurrentProfile;if(p!=null)System.Diagnostics.Process.Start(p.Source);});footer.Controls.Add(source,1,0);var save=Style.Button("Save all setups",(a,b)=>{if(Commit()){DialogResult=DialogResult.OK;Close();}});save.AccessibleName="Save all setups";footer.Controls.Add(save,2,0);root.Controls.Add(footer,0,2);AcceptButton=save;
 smartOption.CheckedChanged+=(a,b)=>{if(!loading&&smartOption.Checked)SetType(true);};customOption.CheckedChanged+=(a,b)=>{if(!loading&&customOption.Checked)SetType(false);};camera.SelectionChangeCommitted+=(a,b)=>{if(camera.SelectedItem is DeviceProfile)SelectDevice(((DeviceProfile)camera.SelectedItem).Id);else SelectOther(false);};telescope.SelectionChangeCommitted+=(a,b)=>{if(telescope.Text=="Other")SelectOther(true);else SelectDevice(EquipmentLibrary.SmartProfile(telescope.Text,"Tele").Id);};overrideGain.CheckedChanged+=(a,b)=>{if(!loading)UpdateControls();};foreach(var field in new[]{focal,aperture,sw,sh})field.ValueChanged+=(a,b)=>UpdateFrame();list.SelectedIndexChanged+=(a,b)=>{if(loading)return;int next=list.SelectedIndex;if(!Commit()){loading=true;list.SelectedIndex=editing;loading=false;return;}LoadRig(next);};RefreshList(Math.Max(0,Math.Min(settings.Active,Rigs.Count-1)));
 }
 internal static TextBox Input(){return new TextBox{Font=new Font("Segoe UI",10),Dock=DockStyle.Fill,Margin=new Padding(0),AutoSize=false};}
 internal static Control Field(string title,Control input){var box=Style.Grid(1,21,-100);box.Margin=new Padding(0,0,8,4);box.Controls.Add(Style.Label(title,9.5f),0,0);input.Dock=DockStyle.Fill;input.Margin=new Padding(0);box.Controls.Add(input,0,1);return box;}
 Control Optical(string title,NumericUpDown input){var slot=new Panel{Dock=DockStyle.Fill,Margin=new Padding(0)};var value=Style.Label("",10);opticalValues.Add(value);slot.Controls.Add(input);slot.Controls.Add(value);return Field(title,slot);}
 DeviceProfile CurrentProfile {get{return EquipmentLibrary.All.FirstOrDefault(p=>p.Id==profileId);}}
 internal static NumericUpDown Number(decimal min,decimal max,int digits){return new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=digits,Font=new Font("Segoe UI",10),Dock=DockStyle.Fill,Margin=new Padding(0)};}
 static void Set(NumericUpDown field,double value){field.Value=Math.Max(field.Minimum,Math.Min(field.Maximum,(decimal)value));}
 void RefreshList(int selected){loading=true;list.Items.Clear();foreach(var rig in Rigs)list.Items.Add(rig.Name);list.SelectedIndex=selected;loading=false;LoadRig(selected);}
 void LoadRig(int index){if(index<0)return;editing=index;var rig=Rigs[index];loading=true;var device=EquipmentLibrary.Find(rig);profileId=device?.Id;smart=EquipmentLibrary.Smart(rig);name.Text=rig.Name;smartOption.Checked=smart;customOption.Checked=!smart;camera.SelectedItem=device!=null&&!device.Smart?(object)device:"Other";telescope.SelectedItem=smart?EquipmentLibrary.SmartFamily(rig):"Other";if(telescope.SelectedIndex<0)telescope.SelectedItem="Other";otherName.Text=device==null?rig.Camera:"";Set(focal,rig.Focal);Set(aperture,rig.Aperture);Set(sw,rig.SensorW);Set(sh,rig.SensorH);mount.SelectedItem=rig.Mount;allowed.Text=rig.AllowedSubs??"";overrideGain.Checked=rig.GainOverride.HasValue;Set(gain,rig.GainOverride??device?.GainStart??0);filter.Checked=rig.Filter;mosaic.Checked=rig.Mosaic;if(index<list.Items.Count)list.Items[index]=rig.Name;loading=false;UpdateControls();UpdateFrame();}
 void SetType(bool isSmart){smart=isSmart;profileId=null;loading=true;camera.SelectedItem="Other";telescope.SelectedItem="Other";otherName.Text="";allowed.Text="";overrideGain.Checked=false;loading=false;if(isSmart){Set(focal,0);Set(aperture,0);Set(sw,0);Set(sh,0);mount.SelectedItem="Alt-az / smart telescope";}UpdateControls();UpdateFrame();}
 public void SelectOther(bool isSmart){loading=true;smart=isSmart;profileId=null;smartOption.Checked=isSmart;customOption.Checked=!isSmart;camera.SelectedItem="Other";telescope.SelectedItem="Other";otherName.Text="";allowed.Text="";overrideGain.Checked=false;loading=false;if(isSmart){Set(focal,0);Set(aperture,0);Set(sw,0);Set(sh,0);}else{Set(sw,0);Set(sh,0);}UpdateControls();UpdateFrame();}
 public void SelectDevice(string id){if(editing<0)return;var device=EquipmentLibrary.All.Single(p=>p.Id==id);var rig=new Rig{Name=name.Text,Camera=otherName.Text,Focal=(double)focal.Value,Aperture=(double)aperture.Value,SensorW=(double)sw.Value,SensorH=(double)sh.Value,Mount=mount.Text,Filter=filter.Checked,Mosaic=mosaic.Checked};EquipmentLibrary.Apply(rig,device);EquipmentLibrary.NormalizeSmartRig(rig);Rigs[editing]=rig;LoadRig(editing);}
 void EditOtherSpecs(){var rig=new Rig{Focal=(double)focal.Value,Aperture=(double)aperture.Value,SensorW=(double)sw.Value,SensorH=(double)sh.Value};using(var dialog=new OpticalSpecsForm(rig)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;Set(focal,rig.Focal);Set(aperture,rig.Aperture);Set(sw,rig.SensorW);Set(sh,rig.SensorH);UpdateFrame();}}
 void UpdateControls(){if(info==null||source==null)return;var device=CurrentProfile;cameraField.Visible=!smart;telescopeField.Visible=smart;otherField.Visible=device==null;otherSpecs.Visible=smart&&device==null;exposureField.Visible=smart;overrideGain.Visible=!smart;smartGain.Visible=smart;gain.Visible=!smart;gain.Enabled=!smart&&overrideGain.Checked;source.Enabled=device!=null;if(smart&&overrideGain.Checked)overrideGain.Checked=false;var numbers=new[]{focal,aperture,sw,sh};for(int i=0;i<numbers.Length;i++){numbers[i].Visible=!smart;opticalValues[i].Visible=smart;}info.Text=device==null?(EquipmentLibrary.Error!=""?EquipmentLibrary.Error:smart?"Other smart telescope: enter its name, specifications and app-supported exposures. Gain stays app-controlled.":"Other camera: enter the model name, optics and sensor dimensions; optionally set a calibrated gain."):device.Smart?EquipmentLibrary.SmartFamily(Rigs[editing])+(EquipmentLibrary.HasLenses(Rigs[editing])?" · Choose the lens beside Shoot with on the main screen.":" · Telescope optics loaded.")+"\n"+device.GainGuidance:device.Name+" · reviewed "+device.VerifiedOn+"\n"+device.GainGuidance;}
 void UpdateFrame(){var numbers=new[]{focal,aperture,sw,sh};for(int i=0;i<opticalValues.Count;i++)opticalValues[i].Text=numbers[i].Value>0?numbers[i].Value.ToString(i<2?"0.#":"0.###"):"Not supplied";if(preview!=null)preview.Text=focal.Value>0&&sw.Value>0&&sh.Value>0?"Single frame  "+(2*Math.Atan((double)sw.Value/(2*(double)focal.Value))*180/Math.PI).ToString("0.00")+"° × "+(2*Math.Atan((double)sh.Value/(2*(double)focal.Value))*180/Math.PI).ToString("0.00")+"°":"Enter optics and sensor dimensions to calculate framing.";}
 public bool Commit(){if(editing<0)return true;var device=CurrentProfile;if(string.IsNullOrWhiteSpace(name.Text)||(device==null&&string.IsNullOrWhiteSpace(otherName.Text))||mount.SelectedIndex<0||focal.Value<=0||aperture.Value<=0||sw.Value<=0||sh.Value<=0){info.Text=smart&&device==null?"Enter a setup/model name and use Enter telescope specifications before saving.":"Enter a setup/model name, mount and positive optics / sensor dimensions before saving.";return false;}if(smart&&!string.IsNullOrWhiteSpace(allowed.Text)&&allowed.Text.Split(',').Any(x=>{double value;return !double.TryParse(x.Trim(),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||value<=0||value>3600||(device?.MaxSub.HasValue==true&&value>device.MaxSub.Value)||(device?.Id=="Seestar S50"&&!device.AllowedSubs.Contains(value));})){info.Text="Use only app-confirmed exposures within this model's limits.";return false;}
 var rig=Rigs[editing];rig.Name=name.Text.Trim();rig.Camera=device==null?otherName.Text.Trim():device.Name;rig.DeviceProfileId=profileId;rig.CustomDevice=device==null;rig.SmartDevice=smart;rig.SmartModel=smart?(device==null?"Other":EquipmentLibrary.SmartFamily(rig)):null;rig.Focal=(double)focal.Value;rig.Aperture=(double)aperture.Value;rig.SensorW=(double)sw.Value;rig.SensorH=(double)sh.Value;rig.Mount=mount.Text;rig.CaptureModel=smart&&device==null?"Other smart telescope":"Auto";rig.AllowedSubs=smart?allowed.Text.Trim():"";rig.GainOverride=!smart&&overrideGain.Checked?(double?)gain.Value:null;rig.Filter=filter.Checked;rig.Mosaic=mosaic.Checked;loading=true;list.Items[editing]=rig.Name;loading=false;UpdateControls();return true;}
}
class OpticalSpecsForm:Form {
 public OpticalSpecsForm(Rig rig){Style.Form(this);Text="Other telescope specifications";Style.FitScreen(this,610,310);var root=Style.Grid(2,41,56,56,-100,39);root.Padding=new Padding(12);var title=Style.Label("Enter this telescope's specifications",13,true);root.Controls.Add(title,0,0);root.SetColumnSpan(title,2);var focal=EquipmentForm.Number(0,10000,1);var aperture=EquipmentForm.Number(0,1000,1);var width=EquipmentForm.Number(0,100,3);var height=EquipmentForm.Number(0,100,3);focal.Value=(decimal)rig.Focal;aperture.Value=(decimal)rig.Aperture;width.Value=(decimal)rig.SensorW;height.Value=(decimal)rig.SensorH;root.Controls.Add(EquipmentForm.Field("Focal length (mm)",focal),0,1);root.Controls.Add(EquipmentForm.Field("Aperture (mm)",aperture),1,1);root.Controls.Add(EquipmentForm.Field("Sensor width (mm)",width),0,2);root.Controls.Add(EquipmentForm.Field("Sensor height (mm)",height),1,2);var message=Style.Label("Use the manufacturer's values for the selected lens.",9);root.Controls.Add(message,0,3);root.SetColumnSpan(message,2);root.Controls.Add(Style.Button("Cancel",(a,b)=>Close()),0,4);var save=Style.Button("Use specifications",(a,b)=>{if(focal.Value<=0||aperture.Value<=0||width.Value<=0||height.Value<=0){message.Text="Enter four positive values.";return;}rig.Focal=(double)focal.Value;rig.Aperture=(double)aperture.Value;rig.SensorW=(double)width.Value;rig.SensorH=(double)height.Value;DialogResult=DialogResult.OK;Close();});root.Controls.Add(save,1,4);AcceptButton=save;Controls.Add(root);}
}
